-- # Lernfeld 5: Cyberphysische Systeme > ## Testgetriebene Entwicklung > - Grundprinzipien > - Schreiben von Tests vor Code

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist das Schreiben von Tests vor dem Code ein zentrales Prinzip der testgetriebenen Entwicklung (TDD)?', 2, '[{"text": "Ja", "correct": true, "because": "Kernprinzip von TDD"}, {"text": "Nein", "correct": false, "because": "Grundlage des TDD-Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann TDD ohne das Schreiben von Tests vor dem Code effektiv umgesetzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Tests vor Code definieren Verhalten"}, {"text": "Ja", "correct": false, "because": "Abweichung vom TDD-Prinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Tests, die vor dem Code geschrieben werden, zunächst fehlschlagen?', 2, '[{"text": "Ja", "correct": true, "because": "Rot-Phase ist Teil des Zyklus"}, {"text": "Nein", "correct": false, "because": "Fehlschlag erwartet"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Tests vor dem Code in TDD alle Anforderungen sofort abdecken?', 2, '[{"text": "Nein", "correct": true, "because": "Iterative Entwicklung üblich"}, {"text": "Ja", "correct": false, "because": "Tests wachsen mit Anforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Schreiben von Tests vor dem Code die Planung der Implementierung ersetzen?', 2, '[{"text": "Nein", "correct": true, "because": "Tests spezifizieren, Planung ergänzt"}, {"text": "Ja", "correct": false, "because": "Ergänzung nötig"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das Schreiben von Tests vor dem Code in TDD?', 2, '[{"text": "Spezifikation des erwarteten Verhaltens", "correct": true, "because": "Tests definieren Anforderungen"}, {"text": "Optimierung der Laufzeit", "correct": false, "because": "Nicht primär"}, {"text": "Dokumentation der Implementierung", "correct": false, "because": "Nebenprodukt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt folgt in TDD direkt auf das Schreiben eines Tests vor dem Code?', 3, '[{"text": "Test ausführen und fehlschlagen lassen", "correct": true, "because": "Rot-Phase im Zyklus"}, {"text": "Code implementieren", "correct": false, "because": "Nach Fehlschlag"}, {"text": "Test dokumentieren", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich aus dem Schreiben von Tests vor dem Code?', 2, '[{"text": "Klarheit über Anforderungen", "correct": true, "because": "Tests als Spezifikation"}, {"text": "Schnellere Kompilierung", "correct": false, "because": "Nicht primär"}, {"text": "Weniger Testaufwand", "correct": false, "because": "Aufwand bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip von TDD wird durch das Schreiben von Tests vor dem Code betont?', 2, '[{"text": "Testgetriebene Spezifikation", "correct": true, "because": "Tests leiten Entwicklung"}, {"text": "Maximale Abdeckung", "correct": false, "because": "Ziel, nicht Prinzip"}, {"text": "Manuelle Validierung", "correct": false, "because": "Automatisierung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Schreiben von Tests vor dem Code im TDD-Zyklus?', 2, '[{"text": "Startpunkt des Entwicklungsprozesses", "correct": true, "because": "Beginnt Rot-Phase"}, {"text": "Abschluss der Entwicklung", "correct": false, "because": "Anfang, nicht Ende"}, {"text": "Optimierungsschritt", "correct": false, "because": "Refactoring später"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Schreiben von Tests vor dem Code in TDD?', 4, '[{"text": "Klarheit über Anforderungen", "correct": true, "because": "Tests spezifizieren"}, {"text": "Frühe Fehlererkennung", "correct": true, "because": "Fehlschläge sofort sichtbar"}, {"text": "Langsamere Entwicklung", "correct": false, "because": "Eher schneller"}, {"text": "Bessere Codequalität", "correct": true, "because": "Tests erzwingen Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden beim Schreiben von Tests vor dem Code in TDD berücksichtigt?', 3, '[{"text": "Anforderungen", "correct": true, "because": "Tests spiegeln diese wider"}, {"text": "Erwartetes Verhalten", "correct": true, "because": "Tests definieren Verhalten"}, {"text": "Implementierungsdetails", "correct": false, "because": "Nicht primär"}, {"text": "Akzeptanzkriterien", "correct": true, "because": "Bestimmen Erfolg"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien unterstützt das Schreiben von Tests vor dem Code in TDD?', 3, '[{"text": "Testgetriebene Entwicklung", "correct": true, "because": "Kernprinzip"}, {"text": "Iterative Entwicklung", "correct": true, "because": "Tests wachsen mit Code"}, {"text": "Umfassende Dokumentation", "correct": false, "because": "Sekundär"}, {"text": "Minimale Implementierung", "correct": true, "because": "Nur nötiger Code"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es beim Schreiben von Tests vor dem Code in TDD?', 4, '[{"text": "Hoher Anfangsinvest", "correct": true, "because": "Tests vorab schreiben"}, {"text": "Unklare Anforderungen", "correct": true, "because": "Tests schwer definierbar"}, {"text": "Schnelle Implementierung", "correct": false, "because": "Nicht Herausforderung"}, {"text": "Anpassung bei Änderungen", "correct": true, "because": "Tests müssen mitangepasst werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind beim Schreiben von Tests vor dem Code in TDD entscheidend?', 3, '[{"text": "Testfälle", "correct": true, "because": "Definieren Verhalten"}, {"text": "Anforderungsverständnis", "correct": true, "because": "Basis für Tests"}, {"text": "Code-Komplexität", "correct": false, "because": "Nicht primär"}, {"text": "Automatisierung", "correct": true, "because": "Sichert Effizienz"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Tests vor dem Code sind optional in TDD. b) Tests vor dem Code definieren Anforderungen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Tests Pflicht, definieren Verhalten"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Tests vor dem Code können zunächst fehlschlagen. b) TDD erfordert keine Tests vor dem Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlschlag erwartet, Tests zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Schreiben von Tests vor dem Code verbessert die Codequalität. b) Tests vor dem Code sind in TDD zeitaufwendig.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Qualität steigt, Aufwand real"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Tests vor dem Code ersetzen die Implementierungsplanung. b) Tests vor dem Code fördern frühe Fehlererkennung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Planung ergänzt, Fehler früh sichtbar"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Schreiben von Tests vor dem Code ist in TDD iterativ. b) Tests vor dem Code garantieren fehlerfreien Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Iterativ korrekt, keine Garantie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

